import dspy


class ToyProgram(dspy.Module):
    def forward(self, question):
        return dspy.Prediction(answer=question.upper())


def exact_match(example, prediction):
    return example.answer == prediction.answer


devset = [dspy.Example(question='a', answer='A').with_inputs('question')]

try:
    dspy.Evaluate(devset=devset, metric=exact_match, return_outputs=True)
except ValueError as e:
    legacy_error = str(e)
else:
    raise AssertionError('Expected the legacy flag to raise ValueError')

result = dspy.Evaluate(devset=devset, metric=exact_match, display_progress=False)(ToyProgram())
print(legacy_error)
print(result.results)

assert 'return_outputs' in legacy_error
assert len(result.results) == 1
assert result.results[0][1].answer == 'A'
assert result.results[0][2] is True
```

