import dspy


def inspect_example(example):
    return {'question': example.question, 'answer': example.answer}


example = dspy.Example(question='Why?', answer='Because.').with_inputs('question')

try:
    dspy.Parallel(num_threads=1, disable_progress_bar=True)([(inspect_example, example)])
except TypeError as e:
    default_error = str(e)
else:
    raise AssertionError('Expected default Example unpacking to fail for this worker')

result = dspy.Parallel(
    num_threads=1,
    access_examples=False,
    disable_progress_bar=True,
)([(inspect_example, example)])[0]

print(default_error)
print(result)

assert 'unexpected keyword argument' in default_error
assert result == {'question': 'Why?', 'answer': 'Because.'}
