    }
]))

init_kwargs = []
call_kwargs = []


class FakeEvaluate:
    def __init__(self, *args, **kwargs):
        init_kwargs.append(kwargs.copy())

    def __call__(self, program, **kwargs):
        call_kwargs.append(kwargs.copy())
